var t=`0804-koeksisters`;var s=`world-0804`;var n=`ZA`;var r=`southern-africa`;var a=8;var o=61;var u={en:`Koeksisters`,ua:`Куксістерс`};var d={en:`Koeksisters is a South Africa dish made with all-purpose flour, chicken egg, baking powder, lemon juice. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Куксістерс, страва кухні країни Південно-Африканська Республіка. Основні складники: пшеничне борошно універсальне, куряче яйце, розпушувач тіста, лимонний сік. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,400,`g`],[`unsalted-butter`,55,`g`],[`chicken-egg`,1,`pcs`],[`baking-powder`,10,`g`],[`water`,175,`ml`],[`table-salt`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry twisted koeksisters in small batches until deeply golden and cooked through, then drain briefly.`,ua:`Смажте скручені косички куксістерс невеликими партіями до глибокого золотистого кольору й повної готовності, потім обсушіть.`,t:[`deep-frying`],m:18,i:[[`sunflower-oil`,750,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 10 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 10 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:10,i:[[`white-granulated-sugar`,350,`g`],[`water`,200,`ml`],[`lemon-juice`,20,`ml`],[`ground-ginger`,3,`g`]]},{en:`Dip each hot fried koeksister immediately into cold syrup and allow it to absorb the glaze.`,ua:`Одразу занурюйте кожну гарячу обсмажену косичку в холодний сироп, дайте просочитися.`,t:[`sugar-syrup-cooking`],m:3,i:[]}];var g={slug:t,id:s,country:`ZA`,region:r,servings:8,minutes:61,title:u,text:d,steps:l};export{n as country,g as default,s as id,o as minutes,r as region,a as servings,t as slug,l as steps,d as text,u as title};